package glitch

import data.glitch_lib

check_overly_permissive_policy(value) {
    value.ir_type == "String"
    value.value == "*"
}

check_root_user(value) {
    value.ir_type == "String"
    value.value == "0"
} else {
    value.ir_type == "Integer"
    value.value == 0
}

check_privileged_mode(value) {
    value.ir_type == "Boolean"
    value.value == true
}

check_permissions_777(value) {
    value.ir_type == "String"
    regex.match("777", value.value)
} else {
    value.ir_type == "Integer"
    value.value == 777
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for overly permissive IAM policies
    attr.name in {"Action", "Resource", "permissions", "effect"}
    check_overly_permissive_policy(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Overly permissive policy detected - Granting excessive privileges violates principle of least privilege. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for privileged container execution
    attr.name in {"privileged", "runAsUser", "runAsGroup"}
    check_root_user(attr.value) or check_privileged_mode(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Privileged container/process execution detected - Running with elevated privileges increases attack surface. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for unrestricted filesystem permissions
    attr.name == "permissions"
    check_permissions_777(attr.value)

    result := {
        "type": "sec_def_admin",
        "element": attr,
        "path": parent.path,
        "description": "Unrestricted filesystem permissions detected - World-writable files violate least privilege. (CWE-250)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

