    attr.name == "securityContext"
    has_security_context = true

    not has_security_context

    result := {
        "type": "sec_def_admin",
        "element": node,
        "path": parent.path,
        "description": "Missing security context detected - Defaults to permissive settings, allowing privilege escalation. (CWE-250)"
    }
}

